<?php
require 'db.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$full=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$pw=$_POST['password']??'';if(strlen($pw)<8)$error='Use a password with at least 8 characters.';else{$s=$conn->prepare('INSERT INTO users(FullName,UserName,Email,PhoneNumber,Password,RoleID) VALUES(?,?,?,?,?,2)');$hash=password_hash($pw,PASSWORD_DEFAULT);$s->bind_param('sssss',$full,$username,$email,$phone,$hash);if($s->execute()){flash('Account created. Please sign in.');header('Location: login.php');exit;}else $error='Username or email is already registered.';}}
page_start('Create account');?><div class="form-container" style="margin:35px auto"><h2>Create your account</h2><p class="muted">Join to order from great local restaurants.</p><?php if($error):?><p class="pill"><?=h($error)?></p><?php endif;?><form method="post"><?php csrf_field();?><label>Full name</label><input class="field" name="full_name" required maxlength="120"><label>Username</label><input class="field" name="username" required maxlength="60"><label>Email</label><input class="field" type="email" name="email" required><label>Phone</label><input class="field" name="phone" autocomplete="tel"><label>Password</label><input class="field" type="password" name="password" minlength="8" required><button>Create account</button></form><p>Already registered? <a href="login.php">Sign in</a></p></div><?php page_end();
